def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        i += 1  # consume closing quote
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                raise ValueError('Quoted field with no closing quote')
            if i < n and line[i] != ',':
                raise ValueError('Anything but a comma after a closing quote')
            fields.append(''.join(field_chars))
            if i < n and line[i] == ',':
                i += 1
        else:
            start = i
            while i < n and line[i] not in (',', '"'):
                i += 1
            if i < n and line[i] == '"':
                raise ValueError('Double quote in an unquoted field')
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    if line.endswith(','):
        fields.append('')
    if line == '':
        return ['']
    return fields

def test():
    def check(line, expected):
        try:
            res = parse_csv_line(line)
            ok = res == expected
            if not ok:
                print(f'FAIL: {repr(line)} -> expected {expected}, got {res}')
            return ok
        except Exception as e:
            print(f'ERROR: {repr(line)} raised {e}')
            return False

    all_pass = True
    # Provided examples
    all_pass &= check('a,b,c', ['a','b','c'])
    all_pass &= check('"a,b",c', ['a,b','c'])
    all_pass &= check('"""say ""hi""",x', ['say "hi"','x']))  # Wait still wrong
    # Let's just write the line directly:
    line3 = '"say ""hi""",x'
    all_pass &= check(line3, ['say "hi"','x'])
    # Additional
    all_pass &= check('', [''])
    all_pass &= check('""', [''])
    all_pass &= check(',""', ['', ''])
    all_pass &= check('a,"b,c",d', ['a','b,c','d'])
    # Errors
    for err in ['a"b', '"unterminated', '"abc"d', '"abc","def"ghi']:
        try:
            parse_csv_line(err)
            print(f'FAIL error: {repr(err)} should raise')
            all_pass = False
        except ValueError:
            pass
        except Exception as e:
            print(f'UNEXPECTED: {repr(err)} raised {e}')
            all_pass = False
    if all_pass:
        print('ALL TESTS PASSED')
    else:
        print('SOME TESTS FAILED')

if __name__ == '__main__':
    test()

